function deposit() external payable {
    require(msg.value > 0, "zero deposit");
    deposits[msg.sender] += msg.value;
    emit Deposited(msg.sender, msg.value);
}

pragma solidity ^0.8.20;
contract LearningVault {
    address public immutable owner;
    mapping(address => uint256) public deposits;
    uint256 public total;
    event Deposited(address indexed user, uint256 amount);
    event Withdrawn(address indexed to, uint256 amount);
    constructor() { owner = msg.sender; }
    function deposit() external payable { require(msg.value > 0); deposits[msg.sender] += msg.value; total += msg.value; emit Deposited(msg.sender, msg.value); }
    function withdraw(uint256 amount) external { require(msg.sender == owner, "not owner"); require(amount <= total, "insufficient"); total -= amount; (bool ok,) = payable(owner).call{value: amount}(""); require(ok, "transfer failed"); emit Withdrawn(owner, amount); }
}
